const results = items.map(item => ({
  title: item.json.title?.rendered || item.json.title,
  link: item.json.link,
  id: item.json.id
}));
const summary = results.map(r => '• ' + r.title + '\n  ID: ' + r.id + ' → ' + r.link).join('\n\n');
return [{ json: { count: results.length, results, summary } }];
